referenceSolutions.python:
def selectionProofFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    sums=set()
    def visit(i,s):
        if i==len(a):
            sums.add(s)
            return
        visit(i+1,s)
        visit(i+1,s+a[i])
    visit(0,0)
    out=sorted(sums)
    return next((x for x in out if x>=k),-1)

